typedef enum{BASE_ADD,BASE_NOT,BASE_XOR}BaseMode;typedef struct{uint32_t data_off,first_index,word_count,seed_off,check_off;BaseMode mode0;uint32_t key0,key1,key2;}Block;
static const Block k[6]={{0x000,0,92,0x170,0x174,BASE_ADD,0,0xE1E1E1E1u,0x57575757u},{0x180,96,12,0x1B0,0x1B4,BASE_NOT,0,0x33333333u,0xCCCCCCCCu},{0x1C0,112,12,0x1F0,0x1F4,BASE_XOR,0x69696969u,0x2B2B2B2Bu,0xB8B8B8B8u},{0x200,128,92,0x370,0x374,BASE_ADD,0,0x1E1E1E1Eu,0x75757575u},{0x380,224,1644,0x1D30,0x1D34,BASE_NOT,0,0x33333333u,0xCCCCCCCCu},{0x1D40,1872,104,0x1EE0,0x1EE4,BASE_XOR,0x96969696u,0xB2B2B2B2u,0x8B8B8B8Bu}};
static uint32_t r32(const uint8_t*p){return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}static void w32(uint8_t*p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}static uint32_t rol16(uint32_t x){return(x<<16)|(x>>16);}static void ex(const uint8_t*b,const Block*x,uint32_t o[3]){uint32_t s0=0,s1=0,s2=0,seed=r32(b+x->seed_off);for(uint32_t n=0;n<x->word_count;n++){uint32_t idx=x->first_index+n,w=r32(b+x->data_off+n*4);s0+=rol16(w);if(idx&1)s1+=w^(seed+idx);else s2+=w^(seed+idx);}o[0]=x->mode0==BASE_ADD?seed+s0:x->mode0==BASE_NOT?(~seed)+s0:(seed^x->key0)+s0;o[1]=(seed^x->key1)+s1;o[2]=(seed^x->key2)+s2;}
static void master(const uint8_t*b,uint32_t o[4]){uint32_t sa=r32(b+0x170),sb=r32(b+0x1B0),sc=r32(b+0x1F0),sd=r32(b+0x370),se=r32(b+0x1D30),sf=r32(b+0x1EE0);uint32_t a0=r32(b+0x174),b0=r32(b+0x1B4),c0=r32(b+0x1F4),d0=r32(b+0x374),e0=r32(b+0x1D34),f0=r32(b+0x1EE4),a1=r32(b+0x178),b1=r32(b+0x1B8),c1=r32(b+0x1F8),d1=r32(b+0x378),e1=r32(b+0x1D38),f1=r32(b+0x1EE8),a2=r32(b+0x17C),b2=r32(b+0x1BC),c2=r32(b+0x1FC),d2=r32(b+0x37C),e2=r32(b+0x1D3C),f2=r32(b+0x1EEC);uint32_t x=((a0+b0)^sa)+((c0+d0)^sc)+((e0+f0)^se),y=((a1+b1)^sb)+((c1+d1)^sd)+((e1+f1)^sf),z=((a2+b2)^sa)+((c2+d2)^sb)+((e2+f2)^sc);o[0]=(~x)+(y^0xAAAAAAAAu)+(z^0x55555555u);o[1]=x;o[2]=y;o[3]=z;}
bool mml_retail_save_generate_checks(uint8_t*b,size_t n,const uint32_t seeds[6]){if(!b||!seeds||n!=MML_RETAIL_TRANSFER_SIZE)return false;for(unsigned i=0;i<6;i++){w32(b+k[i].seed_off,seeds[i]);uint32_t o[3];ex(b,&k[i],o);w32(b+k[i].check_off,o[0]);w32(b+k[i].check_off+4,o[1]);w32(b+k[i].check_off+8,o[2]);}uint32_t m[4];master(b,m);for(int i=0;i<4;i++)w32(b+0x1EF0+i*4,m[i]);return true;}
MMLRetailSaveResult mml_retail_save_verify(const uint8_t*b,size_t n){if(!b)return MML_RETAIL_SAVE_BAD_ARGUMENT;if(n!=MML_RETAIL_TRANSFER_SIZE)return MML_RETAIL_SAVE_BAD_SIZE;for(unsigned i=0;i<6;i++){uint32_t o[3];ex(b,&k[i],o);if(r32(b+k[i].check_off)!=o[0]||r32(b+k[i].check_off+4)!=o[1]||r32(b+k[i].check_off+8)!=o[2])return(MMLRetailSaveResult)(MML_RETAIL_SAVE_BLOCK_A+i);}uint32_t m[4];master(b,m);for(int i=0;i<4;i++)if(r32(b+0x1EF0+i*4)!=m[i])return MML_RETAIL_SAVE_MASTER;return MML_RETAIL_SAVE_OK;}
